import type { AuthConfig } from "convex/server";
import { env } from "./_generated/server";
import { isLocalBackend, isPublicDemoDeployment, LOCAL_DEMO_AUDIENCE, LOCAL_DEMO_ISSUER, PUBLIC_DEMO_AUDIENCE, PUBLIC_DEMO_ISSUER } from "./localDemo";

// Cloud deployments use Clerk. A backend running on this machine is the local presentation mode:
// it trusts only a key pair generated by scripts/demo.ts. The public demo deployment (a fixed name in
// src/domain/local-demo.ts) trusts only its own key pair. Each branch reads only its own variables.
export default {
  providers: isLocalBackend(env.CONVEX_CLOUD_URL)
    ? [{ type: "customJwt", issuer: LOCAL_DEMO_ISSUER, applicationID: LOCAL_DEMO_AUDIENCE, jwks: env.WAREORB_LOCAL_DEMO_JWKS ?? "", algorithm: "ES256" }]
    : isPublicDemoDeployment(env.CONVEX_CLOUD_URL)
      ? [{ type: "customJwt", issuer: PUBLIC_DEMO_ISSUER, applicationID: PUBLIC_DEMO_AUDIENCE, jwks: env.WAREORB_PUBLIC_DEMO_JWKS ?? "", algorithm: "ES256" }]
      : [{ domain: env.CLERK_JWT_ISSUER_DOMAIN ?? "", applicationID: "convex" }],
} satisfies AuthConfig;
